      "title": "1924年のドーズ案を振り返る",
      "body": [
        "まず、第一次世界大戦が終わった時、ヨーロッパは自力で復興できなかったから、1924年の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドーズ案</strong></span>で<strong class=\"source-bold\">アメリカがヨーロッパの<ruby>復興<rt>ふっこう</rt></ruby>を支援</strong>する体制ができたよね。ここでドーズ案の内容をもう一度確認！"
      ],
      "plainBody": [
        "まず、第一次世界大戦が終わった時、ヨーロッパは自力で復興できなかったから、1924年のドーズ案でアメリカがヨーロッパの復興を支援する体制ができたよね。ここでドーズ案の内容をもう一度確認！"
      ],
