      "id": "modern-c04-l18-p02-003",
      "title": "国内改革と連邦政府の経済介入",
      "body": [
        "そして、フーヴァーとローズヴェルトの最大の違いは、<strong class=\"source-bold\">ローズヴェルト</strong>が「<strong class=\"source-bold\">恐慌の原因はアメリカ国内にある</strong>から、国内の改革が必要だ！」と認識して、景気回復のためには<strong class=\"source-bold\">連邦政府（国家）が積極的に経済に<ruby>介入<rt>かいにゅう</rt></ruby></strong>することが必要だ、と考えたことだ。"
      ],
      "plainBody": [
        "そして、フーヴァーとローズヴェルトの最大の違いは、ローズヴェルトが「恐慌の原因はアメリカ国内にあるから、国内の改革が必要だ！」と認識して、景気回復のためには連邦政府（国家）が積極的に経済に介入することが必要だ、と考えたことだ。"
      ],
