      "id": "modern-c04-l18-p02-039",
      "title": "1935年の中立法とその強化",
      "body": [
        "国内では<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">孤立主義</strong></span>が高まり、1935年には<strong class=\"source-bold\">イタリアのエチオピア侵略</strong>への経済<ruby>制裁<rt>せいさい</rt></ruby>から<strong class=\"source-bold\">中立法</strong>が制定されたよ。最初は<strong class=\"source-bold\">交戦国への武器輸出を禁止</strong>するものだったけど、翌年には<strong class=\"source-bold\"><ruby>借款<rt>しゃっかん</rt></ruby>も禁止</strong>されるなど、中立法は徐々に強化されていった。"
      ],
      "plainBody": [
        "国内では孤立主義が高まり、1935年にはイタリアのエチオピア侵略への経済制裁から中立法が制定されたよ。最初は交戦国への武器輸出を禁止するものだったけど、翌年には借款も禁止されるなど、中立法は徐々に強化されていった。"
      ],
