      "title": "恐慌以前から続くイギリスの不景気",
      "body": [
        "第一次世界大戦ののち、<strong class=\"source-bold\">イギリスはずっと不景気</strong>だった。工業生産ではとっくにアメリカやドイツに抜かれてるし、戦後復興もなかなか進まなかったから、イギリスでは<strong class=\"source-bold\">恐慌以前から失業者が100万人を超えていた</strong>よ。"
      ],
