      "body": [
        "これは、イギリス連邦に関税ブロック（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スターリング＝ブロック</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ポンド＝ブロック</strong></span>】</strong>）をつくり、連邦内の貿易にかかる関税は安く、その他の国からの輸入にかかる関税を高くして（これが「<strong class=\"source-bold\">特恵関税制度</strong>」だ）、連邦内の貿易を活発にして恐慌を克服しましょう！ってことだよ。"
      ],
