      "title": "民族共同体からの排除とユダヤ人への迫害",
      "body": [
        "ヒトラーは「<strong class=\"source-bold\">ドイツ民族の優越</strong>」を主張していたから、そのドイツ人の<strong class=\"source-bold\">民族共同体</strong>に合わない人間は排除するという政策をとった。このなかで、排除されるべき人間として標的になったのが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ユダヤ人</strong></span>だよ。"
      ],
      "plainBody": [
        "ヒトラーは「ドイツ民族の優越」を主張していたから、そのドイツ人の民族共同体に合わない人間は排除するという政策をとった。このなかで、排除されるべき人間として標的になったのがユダヤ人だよ。"
      ],
