      "title": "1935年のニュルンベルク法",
      "body": [
        "1935年に制定された<strong class=\"source-bold\">ニュルンベルク法</strong>では、<strong class=\"source-bold\">ユダヤ人の公職追放、企業経営の禁止、財産没収</strong>、そして<strong class=\"source-bold\">ドイツ人との通婚禁止</strong>などが定められた。"
      ],
      "plainBody": [
        "1935年に制定されたニュルンベルク法では、ユダヤ人の公職追放、企業経営の禁止、財産没収、そしてドイツ人との通婚禁止などが定められた。"
      ],
