export const sourcePages = {
  "326": "<h2>326</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第18回</strong></span> <span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">世界恐慌とその影響</strong></span></p>\n<p>いよいよ近現代史も大詰めだよ。今回は<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">世界<ruby>恐慌<rt>きょうこう</rt></ruby>後の欧米各国</strong></u>の動きだ。<ruby>未<rt>み</rt></ruby><ruby>曾有<rt>ぞう</rt></ruby>の大<ruby>不況<rt>ふきょう</rt></ruby>に直面した各国はどうなるんだろう？</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">大きくつかもう！</span></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">1</span> <strong class=\"source-bold\">世界恐慌の発生</strong><br><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">327〜331ページ</span></td><td><span data-source-color=\"red\" style=\"color:#e52715\">➡</span></td><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">2</span> <strong class=\"source-bold\">アメリカの恐慌対策<br>〜ニューディール〜</strong><br><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">331〜333ページ</span></td></tr><tr><td></td><td></td><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">3</span> <strong class=\"source-bold\">英仏の恐慌対策<br>〜ブロック経済の形成〜</strong><br><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">334〜336ページ</span></td></tr><tr><td></td><td></td><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">4</span> <strong class=\"source-bold\">世界恐慌後のドイツ<br>〜ナチス＝ドイツ体制の成立〜</strong><br><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">336〜342ページ</span></td></tr></tbody></table></div>\n<blockquote><p>これまでに経験したことのない大不況を、各国はどうやって克服しようとしたんだろう？</p></blockquote>\n<p>第一次世界大戦の後、ヨーロッパ各国は<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">アメリカに支えられて</strong></u><ruby>復興<rt>ふっこう</rt></ruby>を進めていたけど、アメリカが大不況に陥ると、その経済力に支えられていた<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">ヨーロッパ各国は大打撃を受けた</strong></u>。各国では「自分の国だけなんとかなればいい」という<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">経済ナショナリズム</strong></u>が高まった。<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">ブロック経済</strong></u>、<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">ニューディール</strong></u>……植民地がいっぱいあったり、資源が出るから自力で立ち直る道筋をつくれた、いわゆる「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">持てる国</strong></span>」（米・英・仏など）はまだよかったけど、植民地がない「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">持たざる国</strong></span>」（独・伊・日など）はどうにもならない。こうして1920年代後半に進んでいた「国際協調」の動きが崩れ、ヨーロッパでは<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">ファシズム</strong></u>が台頭し、ドイツでは<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">ナチ党</strong></u>が政権に就いた。今回は<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">各国の国内問題</strong></u>を中心に、<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">恐慌後の欧米諸国</strong></u>の動向を見ていくよ。それじゃあ、始めよう。</p>",
  "327": "<h2>327</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">1</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">世界恐慌の発生</u></p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">1</span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">世界恐慌の発生</strong></span></h3>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">クローズアップ</strong></span> <span data-source-color=\"black\" data-source-background=\"pink\" style=\"color:#222222;background-color:#f0a0a0\"><strong class=\"source-bold\">世界恐慌の発生とアメリカの恐慌対策</strong></span></h3>\n<blockquote><p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">世界恐慌</strong></span>の発生 ［1929.10.24］ ＝ “<strong class=\"source-bold\">暗黒の木曜日</strong>”</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ニューヨーク株式<ruby>市場<rt>しじょう</rt></ruby></strong></span>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ウォール街</strong></span>）での<strong class=\"source-bold\">株価大暴落</strong></p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><strong class=\"source-bold\">金融恐慌</strong>に発展して企業・銀行の<ruby>連鎖<rt>れんさ</rt></ruby>倒産が起き、<strong class=\"source-bold\">大量の失業者</strong>が発生</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">●</span>世界経済の信用悪化……貿易の縮小や信用不安の拡大で、全世界に恐慌が波及</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フーヴァー</strong></span>大統領《<strong class=\"source-bold\">共和党</strong>》の政策 ［任1929〜33］</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><strong class=\"source-bold\">自由放任政策</strong>と<strong class=\"source-bold\">財政<ruby>均衡<rt>きんこう</rt></ruby>の原則</strong>、<strong class=\"source-bold\">各州の自治の原則</strong>を捨てきれず、不況が悪化</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フーヴァー＝モラトリアム</strong></span> ［1931］ ……各国の<ruby>賠償金<rt>ばいしょうきん</rt></ruby>と<ruby>戦債<rt>せんさい</rt></ruby>支払いを<strong class=\"source-bold\">1カ年停止</strong></p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フランクリン＝ローズヴェルト</strong></span>大統領《<strong class=\"source-bold\">民主党</strong>》［任1933〜45］</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">◎</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ニューディール</strong></span>【新規まき直し】……<strong class=\"source-bold\">連邦政府（国家）</strong>が積極的に経済に<ruby>介入<rt>かいにゅう</rt></ruby></p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">全国産業復興法</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">NIRA</strong></span>】</strong> ［1933］</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">農業調整法</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">AAA</strong></span>】</strong> ［1933］</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">テネシー川流域開発公社</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">TVA</strong></span>】</strong> ［1933］</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">➡</span><strong class=\"source-bold\">全国産業復興法・農業調整法</strong>が、最高裁判所において<strong class=\"source-bold\"><ruby>違憲<rt>いけん</rt></ruby>判決</strong> ［1935］</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">◎</span><strong class=\"source-bold\">第2次ニューディール</strong> ［1935〜］</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ワグナー法</strong></span> ［1935］ ……NIRAの<strong class=\"source-bold\">労働者の権利</strong>の部分を分割立法</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">➡</span><strong class=\"source-bold\">産業別組合会議【CIO】</strong>の成立 ［1938］ ……<strong class=\"source-bold\">未熟練労働者中心</strong>の労働組合</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">◎</span>対外政策</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>善隣<rt>ぜんりん</rt></ruby>外交</strong></span>……<strong class=\"source-bold\">ラテンアメリカとの友好</strong>に努める　<span data-source-color=\"gray\" style=\"color:#777777\">➡</span><strong class=\"source-bold\">ドル＝ブロック</strong>の形成</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">キューバ独立</strong></span>の承認 ［1934］ ……<strong class=\"source-bold\">プラット条項の廃止</strong></p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">●</span>対ヨーロッパ政策……伝統的な<strong class=\"source-bold\">孤立主義</strong>への回帰</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><strong class=\"source-bold\">ロンドン世界経済会議</strong> ［1933.6］ <span data-source-color=\"gray\" style=\"color:#777777\">➡</span><strong class=\"source-bold\">アメリカは国際協調を拒否</strong></p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソ連の承認</strong></span> ［1933］ ……<ruby>列強<rt>れっきょう</rt></ruby>諸国中、最後の承認。ソ連への輸出拡大を狙う</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><strong class=\"source-bold\">中立法</strong> ［1935］ ……<strong class=\"source-bold\">交戦国への武器・軍需品輸出の禁止</strong>。その後、<ruby>借款<rt>しゃっかん</rt></ruby>も禁止</p></blockquote>\n<h4><span data-source-color=\"gray\" style=\"color:#777777\"><strong class=\"source-bold\">「ドーズ案」によって「相対的安定期」になったけど……</strong></span></h4>\n<p>教科書だとあんまりちゃんと解説されていないけど、まずは<strong class=\"source-bold\">世界恐慌</strong>の背景をきちんと説明していくよ。あとで各国の政策を理解するのに重要だからね。難しいかもしれないけど、<ruby>頑張<rt>がんば</rt></ruby>ってついてきてね。</p>\n<p>まず、第一次世界大戦が終わった時、ヨーロッパは自力で復興できなかったか</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "328": "<h2>328</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第18回</strong></span> 世界恐慌とその影響</p>\n<p>ら、1924年の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドーズ案</strong></span>で<strong class=\"source-bold\">アメリカがヨーロッパの<ruby>復興<rt>ふっこう</rt></ruby>を支援</strong>する体制ができたよね。ここでドーズ案の内容をもう一度確認！　<strong class=\"source-bold\">アメリカの民間資本</strong>（金融機関）が<strong class=\"source-bold\">ドイツに投資</strong>して復興を助け、ドイツに<ruby>賠償金<rt>ばいしょうきん</rt></ruby>を払わせる。そして、<strong class=\"source-bold\">賠償金をもらった英仏</strong>が復興を進めて、アメリカに<ruby>戦債<rt>せんさい</rt></ruby>（借金）を返す。こうして、アメリカのお金がヨーロッパ全体を回って経済復興が進む、っていう仕組みだ。</p>\n<p>そして復興の道筋がつくと、イギリスもフランスもドイツも冷静になって、「<strong class=\"source-bold\">二度と世界大戦を起こしちゃいけない</strong>」って考えた。だから、1920年代後半には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国際協調</strong></span>が進み、<strong class=\"source-bold\">戦間期のうちで一番平和で安定した時代</strong>だったから「<strong class=\"source-bold\">相対的安定期</strong>」と呼ばれている。ただ、あまりにも<strong class=\"source-bold\">アメリカだけに頼り切る体制</strong>だから、もしアメリカがコケたら……なんか、イヤな予感がするね。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">空前の好景気に浮かれていたアメリカでは、すでに<ruby>不況<rt>ふきょう</rt></ruby>の予感が……</strong></span></h4>\n<p>そうはいっても、<strong class=\"source-bold\">1920年代前半のアメリカ</strong>は<strong class=\"source-bold\">史上空前の好景気</strong>！　大戦中に急増した<strong class=\"source-bold\">ヨーロッパへの輸出</strong>で、工業も農業もやたら<ruby>儲<rt>もう</rt></ruby>かった。そりゃそうだよ……。<strong class=\"source-bold\">ヨーロッパは工業も農業も崩壊</strong>して、アメリカからの輸入でなんとか戦争をしていたんだもん。でも、大戦が終わると戦争での需要がなくなり、実際に大戦直後から<strong class=\"source-bold\">農産物価格が下がって</strong>、農業分野ではすでに不況が始まっていたんだ！。</p>\n<p>じゃあ、工業はどうだろう。大戦直後はヨーロッパの復興が進んでいないから、アメリカ企業は<strong class=\"source-bold\">ヨーロッパへの輸出</strong>で儲かっていた。復興に必要なものから生活必需品まで、とにかくなんでもかんでも売れる！　だから、<strong class=\"source-bold\">アメリカ企業は生産した分だけ売れて儲かる</strong>。つまり「在庫」がないんだよ。だって「在庫」が多いと赤字になるでしょ。こうして、アメリカ企業は「もっと生産量を増やせば、もっと儲かる！」って思って、新工場を建てたり、新しい機械を導入したり、<strong class=\"source-bold\">設備投資</strong>を増やしたんだけど、世の中そんなにうまくいくもんじゃないよ……。</p>\n<p><strong class=\"source-bold\">1926〜27年ごろ</strong>、ヨーロッパ、特にドイツの工業生産は<strong class=\"source-bold\">第一次世界大戦前の水準まで回復</strong>したんだよ。こうなると「なんでもかんでもアメリカから輸入する」ってことはなくなる。しかも、<strong class=\"source-bold\">アメリカの貿易政策</strong>が問題だ！　19世紀後半、後進国だったアメリカは<strong class=\"source-bold\">保護貿易政策</strong>をとっていたけど、<strong class=\"source-bold\">第一次世界大戦後に世界一の経済大国</strong>になったのに、<strong class=\"source-bold\"><ruby>高関税<rt>こうかんぜい</rt></ruby>政策</strong>を続けたんだ。これって「キミのものは買ってあげないけど、オレのものは買えよ！」っていうことだ。ワガママだな。でもこれで、アメリカは自分の首を絞めることになるんだよ。</p>\n<blockquote><p>世界一のアメリカが保護貿易をやったら、他の国は勝てないから保護貿易になるのは当たり前だよ……</p></blockquote>\n<p>ヨーロッパ各国は、自国の産業を守るために<strong class=\"source-bold\">アメリカに対抗して保護貿易</strong>をとり、各国の<strong class=\"source-bold\">高関税政策</strong>によって世界全体の<strong class=\"source-bold\">貿易が縮小</strong>したんだ。こうなると、当然<strong class=\"source-bold\">アメリカの輸出も減る</strong>。しかもア</p>",
  "329": "<h2>329</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">1</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">世界恐慌の発生</u></p>\n<p>メリカ企業は、輸出を見込んだ<strong class=\"source-bold\">過剰な設備投資</strong>をしていたから、生産を増やした分がそのまま在庫になるよ……。</p>\n<p>こうした「<strong class=\"source-bold\">生産過剰</strong>（作り過ぎ）」で<strong class=\"source-bold\">企業の業績が悪化</strong>して労働者の給料は伸び悩み、すでに<strong class=\"source-bold\">農業は不況</strong>だから（<strong class=\"source-bold\">農業<ruby>恐慌<rt>きょうこう</rt></ruby></strong>）、<strong class=\"source-bold\">農民は<ruby>貧困<rt>ひんこん</rt></ruby>に苦しんで</strong>いた。さらに、<strong class=\"source-bold\">設備投資による技術革新</strong>（機械化）で、<strong class=\"source-bold\">失業者が増える</strong>。そして、アメリカ人は「景気が悪いから、ムダ<ruby>遣<rt>づか</rt></ruby>いはやめよう！」って思い始めたんだ。しかも、<strong class=\"source-bold\">クレジットでの分割払い</strong>（教科書には「信用販売／<ruby>月賦<rt>げっぷ</rt></ruby>」って書いてある）が普及して<strong class=\"source-bold\">各家庭での<ruby>負債<rt>ふさい</rt></ruby>が増えていた</strong>から、ますます物を買わなくなる……難しい言葉だと「<strong class=\"source-bold\"><ruby>購買力<rt>こうばいりょく</rt></ruby>の低下</strong>」が起きていたから、企業は販売不振になったんだよ。</p>\n<p>こうして1920年代後半には不況の<ruby>兆候<rt>ちょうこう</rt></ruby>があちこちに現れていたんだけど、アメリカでは不思議なことが起きていたよ。それが「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">株価の異常<ruby>高騰<rt>こうとう</rt></ruby></strong></span>」だ！。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">「株は絶対儲かる！」って神話が生まれ、株式<ruby>市場<rt>しじょう</rt></ruby>は「投資から投機へ」</strong></span></h4>\n<p>だいたい世の中「〇〇は絶対儲かる」って話は、絶対アヤシイ……。投資ってのは、儲かる可能性もあれば、損をするリスクもある！　でも、アメリカでは株神話が生まれていたんだよ。1921年に60ドル程度だった株価は、<strong class=\"source-bold\">大戦後の好景気</strong>でどんどん上がり、それが1年、2年、3年……と続いていたんだ。こうして、あまりにも<strong class=\"source-bold\">株価の上昇が続いた</strong>から、アメリカでは「<strong class=\"source-bold\">株を買えば儲かる</strong>」という神話ができて、みんなが<strong class=\"source-bold\">借金してまで株を買い始めた</strong>。例えばこんな感じ。手持ちの50万円で株を買って儲かった人が、「100万円借りて株を買えば、2倍儲かるのでは？」と思って借金する。で、実際に2倍儲かると「だったら200万円借りれば……」っていうふうにエスカレートして、どんどん借金をして株を買い<ruby>漁<rt>あさ</rt></ruby>ったんだ。</p>\n<p>こうして、株式市場に本来ないはずのお金（借金じゃん……）がどんどん流れ込むと、株だって<strong class=\"source-bold\">需要と<ruby>供給<rt>きょうきゅう</rt></ruby>で価格が決まる</strong>ものだから、1920年代後半には「<strong class=\"source-bold\">景気が後退してるのに、株価だけが上がる</strong>」という異常な状態になった。難しい言葉だと、株式市場に<strong class=\"source-bold\">投機</strong>の資金（要はギャンブルみたいなボロ儲けを狙ったお金）が流入して<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">株価が異常高騰</strong></span>し、1929年には、ついに株価が380ドルを超えた。6倍以上！　こりゃ、いつ「ドカン」と落ちてもおかしくない。</p>\n<p>ていうか、人類は歴史から学んでいないよ。<strong class=\"source-bold\">世界恐慌</strong>は「<strong class=\"source-bold\">株神話</strong>」だけど、1980年代の<strong class=\"source-bold\">日本のバブル経済</strong>は「<strong class=\"source-bold\">土地神話</strong>」だし、2008年の<strong class=\"source-bold\">リーマンショック</strong>（<strong class=\"source-bold\">世界金融危機</strong>）は「<strong class=\"source-bold\">住宅神話</strong>」。最後は全部暴落だ。みんなは「〇〇は絶対儲かる」って神話に踊らされちゃダメだよ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ウォール街で株価が大暴落！　アメリカの不況は、一気に世界に拡大した</strong></span></h4>\n<p>1929年10月24日、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ニューヨーク株式市場</strong></span>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ウォール街</strong></span>）で、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">株価が大暴落</strong></span>した！。「<strong class=\"source-bold\">暗黒の木曜日</strong>」と呼ばれるこの暴落のあと、翌週の火曜日にもさらに暴落が起き、これをきっかけに<strong class=\"source-bold\">アメリカの長い不況</strong>が始まったんだ。まず、すでに輸出の減少や国内での売り上げ減少で業績が悪化していた自動車などの<strong class=\"source-bold\">製造業に大きな打</strong></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "330": "<h2>330</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第18回</strong></span> 世界恐慌とその影響</p>\n<p><strong class=\"source-bold\">撃</strong>を与え、さらに1930年に入ると「この企業や銀行は<ruby>潰<rt>つぶ</rt></ruby>れちゃうんじゃないか？」という<strong class=\"source-bold\">信用不安</strong>が起きて、バタバタと<strong class=\"source-bold\">銀行が<ruby>連鎖<rt>れんさ</rt></ruby>倒産</strong>する<strong class=\"source-bold\">金融<ruby>恐慌<rt>きょうこう</rt></ruby></strong>になったんだ。なんと、1929〜33年の間に倒産した銀行は約9000！　企業の倒産も9万件を超えて、企業の収益も60％も落ち込んだよ。こうしてアメリカでは、<strong class=\"source-bold\">大量の失業者が発生</strong>して（なんと1300万人！）、失業率は25％にもなったんだ。</p>\n<p>こうなると、アメリカ経済に<ruby>復興<rt>ふっこう</rt></ruby>を頼る<strong class=\"source-bold\">ヨーロッパに影響</strong>がないはずがない。<strong class=\"source-bold\">アメリカ資本がヨーロッパから引き揚げる</strong>と、<strong class=\"source-bold\">信用不安が拡大</strong>し、ヨーロッパでも銀行や企業がバタバタと倒産して、大<ruby>不況<rt>ふきょう</rt></ruby>になった。そして信用不安の拡大から、世界貿易は約40％も縮小した。こうなると、ヨーロッパだけじゃなく<strong class=\"source-bold\">アジアにも不況が拡大</strong>し、文字どおりの<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">世界恐慌</strong></span>になったんだ。</p>\n<h3><strong class=\"source-bold\">〈世界恐慌の波及〉</strong></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><span data-source-marker=\"oval\" data-source-border=\"green\" style=\"border:2px solid #315837;border-radius:50%\"><strong class=\"source-bold\">アメリカ</strong><br>株価の大暴落<br>→信用不安</span></td><td><span data-source-marker=\"oval\" data-source-border=\"red\" style=\"border:2px solid #e52715;border-radius:50%\"><strong class=\"source-bold\">ドイツ</strong><br>信用不安が波及<br>→経済危機</span></td></tr><tr><td><span data-source-marker=\"oval\" data-source-border=\"brown\" style=\"border:2px solid #a43725;border-radius:50%\"><strong class=\"source-bold\">イギリス</strong><br>信用不安が波及</span></td><td><span data-source-marker=\"oval\" data-source-border=\"brown\" style=\"border:2px solid #a43725;border-radius:50%\"><strong class=\"source-bold\">フランス</strong><br>信用不安が波及</span></td></tr></tbody></table></div>\n<p><strong class=\"source-bold\">アメリカ資本を引きあげ</strong> <span data-source-marker=\"outline-arrow\" data-source-color=\"green\" data-source-cancellation=\"cross\" data-source-cancellation-color=\"black\" style=\"color:#315837;text-decoration:line-through;text-decoration-color:#222222\">⇨</span></p>\n<p><span data-source-marker=\"outline-arrow\" data-source-color=\"red\" data-source-cancellation=\"cross\" data-source-cancellation-color=\"black\" style=\"color:#e52715;text-decoration:line-through;text-decoration-color:#222222\">⇙</span> <strong class=\"source-bold\">賠償金支払い<br>不能</strong></p>\n<p><span data-source-marker=\"outline-arrow\" data-source-color=\"brown\" data-source-cancellation=\"cross\" data-source-cancellation-color=\"black\" style=\"color:#a43725;text-decoration:line-through;text-decoration-color:#222222\">⇖</span> <strong class=\"source-bold\">戦債支払い不能</strong></p>\n<blockquote><p>アメリカ資本が引き揚げると、ヨーロッパ全体から資本がなくなるんだ……</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">「永遠の繁栄」から一転……恐慌をますます悪化させたフーヴァー大統領</strong></span></h4>\n<p>世界恐慌が起きた時の<strong class=\"source-bold\">アメリカ大統領</strong>は<strong class=\"source-bold\">共和党</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フーヴァー</strong></span>だ。彼は「民間のことは民間でやる」という<strong class=\"source-bold\">自由放任</strong>の原則や、<strong class=\"source-bold\"><ruby>財政均衡<rt>ざいせいきんこう</rt></ruby></strong>の原則（税収が減ったら支出を減らす）を捨てきれなかった。さらに、景気対策はあくまでも「<strong class=\"source-bold\">各州の自治</strong>」の範囲と思っていた。まぁ、これまでの<strong class=\"source-bold\">共和党政権はずっと自由放任</strong>だったもんね。しかも「アメリカだけが回復できればいい！」という<strong class=\"source-bold\">自国中心主義</strong>から、<ruby>関税<rt>かんぜい</rt></ruby>を引き上げる<strong class=\"source-bold\">スムート＝ホーリー関税法</strong>を制定したから、対抗した各国が次々と関税を引き上げる結果となり、ますます<strong class=\"source-bold\">貿易が縮小</strong>して恐慌はさらに悪化した。こうして「<strong class=\"source-bold\">自分の国だけでも助かればいい！</strong>」っていう<strong class=\"source-bold\">経済ナショナリズム</strong>が高まったんだ。</p>\n<p>そして1931年になってやっと<strong class=\"source-bold\">ドイツの深刻な経済危機</strong>に気づいたフーヴァーは、ドイツを助けるために、各国間の支払い義務（<ruby>賠償金<rt>ばいしょうきん</rt></ruby>や<ruby>戦債<rt>せんさい</rt></ruby>など）を<strong class=\"source-bold\">1年間停止</strong>する<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フーヴァー＝モラトリアム</strong></span>を提案したけど、もはや手遅れだよ。すでにヨー</p>",
  "331": "<h2>331</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">2</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">アメリカの恐慌対策　〜ニューディール〜</u></p>\n<p>ロッパにも深刻な不況が波及したあとだ。</p>\n<p>こんな状況にもかかわらず、フーヴァーは「繁栄はすぐそこまできている」と言い続けた。だって彼は、恐慌が長期化している原因は海外にあると思っていたから、まともな対策を考えられるわけがない。1932年になってやっと、<strong class=\"source-bold\">銀行、保険会社などに対する緊急<ruby>融資<rt>ゆうし</rt></ruby></strong>や、<strong class=\"source-bold\">各州の公共事業に対する支援</strong>をやったけど、もはや国民は「共和党じゃダメだぁ〜」って思い始めたよ。</p>\n<blockquote><p>フーヴァーは、恐慌が起こる前は「永遠の繁栄」を<ruby>謳<rt>うた</rt></ruby>い、「<ruby>貧困<rt>ひんこん</rt></ruby>に対して最終的な勝利を得る」って言ってたのにね</p></blockquote>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">2</span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">アメリカの恐慌対策　〜ニューディール〜</strong></span></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">民主党のフランクリン＝ローズヴェルトがニューディールを開始！</strong></span></h4>\n<p>1932年の大統領選挙では「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ニューディール</strong></span> <strong class=\"source-bold\">【</strong>新規まき直し<strong class=\"source-bold\">】</strong>」を公約に掲げて、民主党の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フランクリン＝ローズヴェルト</strong></span>が当選したよ。彼は<strong class=\"source-bold\">ニューヨーク州知事</strong>として積極的な失業対策などをやっていたから、期待も大きかったんだ。そして、フーヴァーとローズヴェルトの最大の違いは、<strong class=\"source-bold\">ローズヴェルト</strong>が「<strong class=\"source-bold\">恐慌の原因はアメリカ国内にある</strong>から、国内の改革が必要だ！」と認識して、景気回復のためには<strong class=\"source-bold\">連邦政府（国家）が積極的に経済に<ruby>介入<rt>かいにゅう</rt></ruby></strong>することが必要だ、と考えたことだ。これが、のちにイギリスの経済学者<strong class=\"source-bold\">ケインズ</strong>が理論化した「<strong class=\"source-bold\">修正資本主義</strong>」だよ。</p>\n<p>それじゃあ、具体的な政策を見ていこう。ローズヴェルトは就任後の「最初の100日間」で、「3つのR（Relief・Recover・Reform）」を目標に次々と改革を進めたよ。まず、恐慌の原因の1つは「<strong class=\"source-bold\">生産過剰</strong>」で<strong class=\"source-bold\">企業の業績が悪化</strong>したことだから、ここを食い止める！　さらに、恐慌克服のためには<strong class=\"source-bold\"><ruby>購買力<rt>こうばいりょく</rt></ruby>を回復</strong>させなきゃダメだ。だって、労働者や農民の収入が下がると、物が売れなくなるから企業の業績が下がり、また給料が下がって……っていうふうに、不況から永遠に抜け出せない。難しい言葉だと「<strong class=\"source-bold\">デフレスパイラル</strong>」に陥るんだ。</p>\n<p>そこでまず、生産過剰を食い止めるために<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">全国産業<ruby>復興<rt>ふっこう</rt></ruby>法</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">NIRA</strong></span>】</strong>をつくった。これは、企業に<strong class=\"source-bold\">価格の協定</strong>（カルテルだよ）<strong class=\"source-bold\">を認め</strong>、競争を抑えて価格を引き上げ、企業に<ruby>利潤<rt>りじゅん</rt></ruby>が出るようにした。同時に<strong class=\"source-bold\">労働者の団結権や団体交渉権</strong>を認めて、労働者の賃金を上げようとしたんだ。さらに農産物の<strong class=\"source-bold\">生産を制限</strong>する<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">農業調整法</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">AAA</strong></span>】</strong>をつくり、農産物価格を上げようとした。この2つの法律は、単に生産を制限するだけでなくて、<strong class=\"source-bold\">労働者や農民の生活を安定</strong>させて、<strong class=\"source-bold\">購買力を回復</strong>させるのも目的だ。そして、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">テネシー川流域開発公社</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">TVA</strong></span>】</strong>を設立して、<strong class=\"source-bold\">大規模な地域開発</strong>で仕事を増やして<strong class=\"source-bold\">失業者を吸収</strong>し、さらにダム建設（ダムには発電所がある！）で安い電力を<ruby>供給<rt>きょうきゅう</rt></ruby>して<strong class=\"source-bold\">電力価格を低下</strong>させたんだ。電力料金が下がれば、企業の生産コストが下がるもんね。</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "332": "<h2>332</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第18回</strong></span> 世界恐慌とその影響</p>\n<h3><strong class=\"source-bold\">〈ニューディール最初の「100日間」〉</strong></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td><span data-source-border=\"gray\" style=\"display:inline-block;border:2px solid #777777;padding:0.3em\"><span data-source-color=\"gray\" style=\"color:#777777\"><strong class=\"source-bold\">恐慌分析</strong></span><br><strong class=\"source-bold\">工業・農業における<span data-source-color=\"red\" style=\"color:#e52715\">生産過剰</span></strong><br><span data-source-marker=\"outline-arrow\" data-source-color=\"black\" style=\"color:#222222\">⇩</span><br><span data-source-border=\"brown\" data-source-border-style=\"dashed\" style=\"display:inline-block;border:1px dashed #a43725\"><span data-source-marker=\"curved-arrow\" data-source-color=\"black\" style=\"color:#222222\">⤴</span><br><strong class=\"source-bold\">企業の<span data-source-color=\"brown\" style=\"color:#a43725\">収益悪化</span> or <span data-source-color=\"brown\" style=\"color:#a43725\">倒産</span></strong><br><span data-source-marker=\"outline-arrow\" data-source-color=\"black\" style=\"color:#222222\">⇩</span><br><strong class=\"source-bold\">労働者の<span data-source-color=\"brown\" style=\"color:#a43725\">減給</span> or <span data-source-color=\"brown\" style=\"color:#a43725\">失業</span></strong><br><span data-source-marker=\"outline-arrow\" data-source-color=\"black\" style=\"color:#222222\">⇩</span><br><strong class=\"source-bold\">消費者の<span data-source-color=\"red\" style=\"color:#e52715\">購買力が低下</span></strong><br><span data-source-marker=\"outline-arrow\" data-source-color=\"black\" style=\"color:#222222\">⇩</span><br><strong class=\"source-bold\">販売不振と在庫の増加</strong></span><br><span data-source-color=\"white\" data-source-background=\"brown\" style=\"color:#ffffff;background-color:#a43725\"><strong class=\"source-bold\">デフレスパイラルに陥る</strong></span></span></td><td><span data-source-marker=\"arrow\" data-source-color=\"red\" style=\"color:#e52715\">⬅</span><br><strong class=\"source-bold\">生産制限</strong><br><br><span data-source-marker=\"arrow\" data-source-color=\"red\" style=\"color:#e52715\">⬅</span><br><strong class=\"source-bold\">購買力の回復</strong></td><td><span data-source-border=\"gray\" style=\"display:inline-block;border:2px solid #777777;padding:0.3em\"><span data-source-color=\"gray\" style=\"color:#777777\"><strong class=\"source-bold\">ニューディール</strong></span><br><span data-source-border=\"black\" style=\"border:1px solid #222222\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">全国産業復興法（NIRA）</strong></span></span><br><span data-source-border=\"black\" style=\"border:1px solid #222222\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">農業調整法（AAA）</strong></span></span><br><br><span data-source-border=\"black\" style=\"border:1px solid #222222\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">テネシー川流域開発公社（TVA）</strong></span></span><br><span data-source-border=\"black\" style=\"border:1px solid #222222\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">全国産業復興法（NIRA）</strong></span></span><br><strong class=\"source-bold\">労働者の団結権・団体交渉権</strong><br><strong class=\"source-bold\">NIRAが違憲となったので……</strong><br><span data-source-marker=\"curved-arrow\" data-source-color=\"black\" style=\"color:#222222\">⤵</span><br><span data-source-border=\"black\" style=\"border:1px solid #222222\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ワグナー法［1935］</strong></span></span><br><strong class=\"source-bold\">労働者の団結権・団体交渉権を分割立法</strong></span></td></tr></tbody></table></div>\n<p>こんなふうに、最初の「100日間」では<strong class=\"source-bold\">失業者の<ruby>救済<rt>きゅうさい</rt></ruby></strong>、生産調整による価格上昇（<strong class=\"source-bold\">デフレの克服</strong>）、さらに入試レベルじゃないけど、銀行預金の保証や株式<ruby>市場<rt>しじょう</rt></ruby>の監視強化など、再び<ruby>恐慌<rt>きょうこう</rt></ruby>が起こらないような対策を進めたよ。そしてローズヴェルトはラジオで政策を国民に直接説明して、協力を求めたんだ。</p>\n<p>ただ、ローズヴェルトの政策もいいことばかりじゃない。1933年に開かれた<strong class=\"source-bold\">ロンドン世界経済会議</strong>では、<ruby>金本位制<rt>きんほんいせい</rt></ruby>の停止をめぐって英仏とアメリカが対立し、<strong class=\"source-bold\">アメリカは国際協調を拒否</strong>して<strong class=\"source-bold\">ドルを切り下げ</strong>、<strong class=\"source-bold\">金本位制を停止</strong>してしまった！。これに反発して各国の経済ナショナリズムがさらに強まったんだよ。</p>\n<h4><span data-source-color=\"gray\" style=\"color:#777777\"><strong class=\"source-bold\">ニューディールへの<ruby>違憲<rt>いけん</rt></ruby>判決で、ローズヴェルトは大衆向けの政策に転換！</strong></span></h4>\n<p>1935年になると、<strong class=\"source-bold\">全国産業復興法【NIRA】</strong>が連邦最高裁判所で<strong class=\"source-bold\">違憲</strong>とされ、翌年には<strong class=\"source-bold\">農業調整法にも違憲判決</strong>が出されたんだ。これは、2つの法律がやろうとしている<strong class=\"source-bold\">生産制限</strong>が、「憲法が保障している<strong class=\"source-bold\">経済活動の自由に違反</strong>してるだろ」って、共和党や資本家が反発した結果だよ。これ以後、資本家を敵に回しちゃったローズヴェルトは、<strong class=\"source-bold\">大衆向けの政策に転換</strong>したんだ（<strong class=\"source-bold\">第2次ニューディール</strong>）。</p>\n<p>まず1935年には、<strong class=\"source-bold\">全国産業復興法から労働者の権利の部分だけ分割</strong>して<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ワグナー法</strong></span>を制定し、改めて<strong class=\"source-bold\">団結権や団体交渉権</strong>を認めると、ローズヴェルトはラジオで「労働者のみなさん、法律はつくったので、あとはみなさんが労働組合をつくって<ruby>頑張<rt>がんば</rt></ruby>ってください」って、労働者を応援した。てか、大統領は応援しかできない。だって、国が労働組合をつくったら社会主義だよ。応援された<strong class=\"source-bold\">不熟練労働者</strong>たちは「こうなりゃ、いっちょオレたちも頑張るかぁ〜」と、新しい労働組合として<strong class=\"source-bold\">産業別組合会議【産業別組織会議】</strong>（最初は産業別労働者組織委員会、略</p>",
  "333": "<h2>333</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">2</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">アメリカの恐慌対策　〜ニューディール〜</u></p>\n<p>称はどちらも<strong class=\"source-bold\">CIO</strong>）をつくった。さらに、連邦政府が<strong class=\"source-bold\">失業保険・退職金・老年年金</strong>を支給する<strong class=\"source-bold\">社会保障法</strong>を制定する時には、やはりラジオで「これこそがニューディールの<ruby>礎<rt>いしずえ</rt></ruby>である！」と訴えたんだよ。ちなみにこの時、<strong class=\"source-bold\">医療保険はない</strong>から正誤問題では気をつけよう！　公的な医療保険制度は、1965年までないからね。</p>\n<blockquote><p>資本家の反発でNIRAが違憲になったから、ローズヴェルトは下層労働者を味方につけようとしたんだ</p></blockquote>\n<p>こうした政策によってローズヴェルトは<strong class=\"source-bold\">下層労働者から絶大な支持</strong>を得て、<strong class=\"source-bold\">2期目の大統領選挙で圧勝</strong>したよ。そして、<strong class=\"source-bold\">黒人</strong>たちも<ruby>奴隷<rt>どれい</rt></ruby>解放をしてくれたリンカンの政党（共和党）よりも、下層労働者を経済的に助けてくれた<strong class=\"source-bold\">ローズヴェルトの政党（民主党）</strong>を自分たちの味方と思うようになった。これ以後、現在まで黒人には民主党支持が多いよ。ほら！　史上初の黒人大統領となったオバマは民主党だよね。</p>\n<h4><span data-source-color=\"gray\" style=\"color:#777777\"><strong class=\"source-bold\">外交では伝統的な孤立主義に回帰。ローズヴェルトの<ruby>善隣<rt>ぜんりん</rt></ruby>外交って？</strong></span></h4>\n<p>1920年代後半、アメリカはヨーロッパの国際協調にかかわってきたけど、<strong class=\"source-bold\">世界恐慌後</strong>は再び<strong class=\"source-bold\">孤立主義に戻っちゃった</strong>。あっ！　アメリカの孤立主義は「モンロー宣言」で示された「<strong class=\"source-bold\">モンロー主義</strong>」だから、<strong class=\"source-bold\">ヨーロッパから孤立</strong>するってことだよ。</p>\n<p>まず、ラテンアメリカに対してこれまでの「<strong class=\"source-bold\"><ruby>棍棒<rt>こんぼう</rt></ruby>外交</strong>」や「<strong class=\"source-bold\">ドル外交</strong>」をやめて、<strong class=\"source-bold\">友好関係を構築</strong>する「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">善隣外交</strong></span>」に転換した。これは「合衆国はラテンアメリカ諸国の“<ruby>善<rt>よ</rt></ruby>き<ruby>隣人<rt>りんじん</rt></ruby>”ですよ」という意味だ。具体的には、<strong class=\"source-bold\">プラット条項を廃止</strong>して<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">キューバの独立</strong></span>を承認し、<strong class=\"source-bold\">パナマやハイチからもアメリカ軍を撤退</strong>させた。まぁ、ホンネの部分では、アメリカが対外輸出の<ruby>復興<rt>ふっこう</rt></ruby>を狙って「南北アメリカが仲良くするかわりに、<strong class=\"source-bold\">アメリカ製品を買ってね</strong>」ってことだけど……。もちろん、これまでのアメリカの態度から考えれば「買ったほうが身のためだぞ」って無言の圧力はある。こうしてできた<strong class=\"source-bold\">南北アメリカの経済的な一体化</strong>は<strong class=\"source-bold\">ドル＝ブロック</strong>といわれている。さらに、植民地では<strong class=\"source-bold\">10年後のフィリピンの独立</strong>を約束したよ。まぁ、10年後は第二次世界大戦の真っ最中だから、実際に独立したのは戦後だけどね。</p>\n<p>そしてヨーロッパに対しては、<strong class=\"source-bold\">輸出の拡大</strong>を狙って<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソ連を承認</strong></span>したけど、国内では<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">孤立主義</strong></span>が高まり、1935年には<strong class=\"source-bold\">イタリアのエチオピア侵略</strong>への経済<ruby>制裁<rt>せいさい</rt></ruby>から<strong class=\"source-bold\">中立法</strong>が制定されたよ。最初は<strong class=\"source-bold\">交戦国への武器輸出を禁止</strong>するものだったけど、翌年には<strong class=\"source-bold\"><ruby>借款<rt>しゃっかん</rt></ruby>も禁止</strong>されるなど、中立法は徐々に強化されていった。これは、アメリカ人の多くが第一次世界大戦に幻滅して、「ヨーロッパの戦争に巻き込まれるのは二度とゴメンだ」と考えていたからだ。あっ！　前回出てきたけど、この中立法があったから、<strong class=\"source-bold\">日中戦争では日本も中国も<ruby>宣戦布告<rt>せんせんふこく</rt></ruby>しなかった</strong>んだよ。</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "334": "<h2>334</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第18回</strong></span> 世界恐慌とその影響</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">3</span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">英仏の恐慌対策　〜ブロック経済の形成〜</strong></span></h3>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">クローズアップ</strong></span> <span data-source-color=\"black\" data-source-background=\"pink\" style=\"color:#222222;background-color:#f0a0a0\"><strong class=\"source-bold\">イギリスの恐慌対策</strong></span></h3>\n<blockquote><p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第5回選挙法改正</strong></span>で<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">男女普通選挙</strong></span>が実現　<span data-source-color=\"gray\" style=\"color:#777777\">➡</span><strong class=\"source-bold\">労働党が第1党</strong>に躍進</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第2次マクドナルド労働党内閣</strong></span>［任1929.6〜31］……<strong class=\"source-bold\">成立直後に<ruby>恐慌<rt>きょうこう</rt></ruby>に直面</strong></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">失業保険の削減</strong></span>　<span data-source-color=\"gray\" style=\"color:#777777\">➡</span>与党（労働党）の信任を失い、<strong class=\"source-bold\">総辞職</strong></p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マクドナルド<ruby>挙国一致<rt>きょこくいっち</rt></ruby>内閣</strong></span> ［任1931〜35］……<strong class=\"source-bold\">実質的には保守党内閣</strong></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>金本位制<rt>きんほんいせい</rt></ruby>の停止</strong></span>［1931］……国際収支の悪化で、維持が困難となり停止</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ウェストミンスター憲章</strong></span> ［1931］ ＝ <strong class=\"source-bold\">イギリス帝国議会</strong> ［1926］ の宣言を法制化</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span>「<strong class=\"source-bold\">本国と自治領が平等</strong>」な<strong class=\"source-bold\">イギリス連邦</strong>が正式に発足</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イギリス連邦経済会議</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">オタワ連邦会議</strong></span>】</strong> ［1932］</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span>恐慌克服のため、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スターリング＝ブロック</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ポンド＝ブロック</strong></span>】</strong> を<ruby>採択<rt>さいたく</rt></ruby></p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span>本国と自治領を<strong class=\"source-bold\"><ruby>特恵関税<rt>とっけいかんぜい</rt></ruby>制度</strong>などで結びつけ、相互通商協定などを<ruby>締結<rt>ていけつ</rt></ruby></p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">恐慌に直面したイギリスでは、マクドナルド挙国一致内閣が成立！</strong></span></h4>\n<p>第一次世界大戦ののち、<strong class=\"source-bold\">イギリスはずっと不景気</strong>だった。工業生産ではとっくにアメリカやドイツに抜かれてるし、戦後復興もなかなか進まなかったから、イギリスでは<strong class=\"source-bold\">恐慌以前から失業者が100万人を超えていた</strong>よ。だから、1928年の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第5回選挙法改正</strong></span>で<strong class=\"source-bold\">21歳以上</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">男女普通選挙</strong></span>が実現すると、1929年の総選挙では<strong class=\"source-bold\">労働党が第1党</strong>になった。こうして6月には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第2次マクドナルド労働党内閣</strong></span>が成立したけど、秋には<strong class=\"source-bold\">世界恐慌</strong>が発生！　こりゃ、とんでもないことになったね。</p>\n<p>とはいえ、イギリスは恐慌による経済の落ち込みはアメリカやドイツに比べれば大きくない……ていうか、最初から景気が悪かったからね。恐慌の影響で<strong class=\"source-bold\">国際収支が赤字</strong>になり失業者も250万人になった！。でも、貧乏な労働者には強い味方がいる！……はず。だって、この時の<strong class=\"source-bold\">首相は労働党のマクドナルド</strong>だ。<strong class=\"source-bold\">人びとは労働党政権に期待</strong>した。……でも、労働党だろうが保守党だろうが、この世界的な経済危機をなんとかする魔法はない。財政危機に直面したマクドナルドは、仕方なく<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">失業保険を削減</strong></span>する<strong class=\"source-bold\"><ruby>緊縮<rt>きんしゅく</rt></ruby>財政</strong>（デフレ政策）をとった。そしたら労働組合が「労働党のくせに労働者に<ruby>飢<rt>う</rt></ruby>え死にしろっていうのかよ」とブチ切れたんだ。このため、与党のはずの<strong class=\"source-bold\">労働党もマクドナルドを批判</strong>したから、1931年に<strong class=\"source-bold\">総辞職</strong>に追い込まれた。こりゃ、イギリスは政治まで危機になっちゃった。</p>\n<p>この政治危機は、<strong class=\"source-bold\">保守党と一部の自由党員</strong>がマクドナルドと協力して挙国一致内閣をつくることで、なんとか収まった。ただ、<strong class=\"source-bold\">マクドナルドは労働党から除名</strong>され、<strong class=\"source-bold\">自由党も分裂</strong>しちゃったから、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マクドナルド挙国一致内閣</strong></span>の主導権は、<strong class=\"source-bold\">実質的</strong></p>",
  "335": "<h2>335</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">3</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">英仏の恐慌対策　〜ブロック経済の形成〜</u></p>\n<p><strong class=\"source-bold\">には保守党</strong>が握ったんだけどね。</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">合</span><span data-source-color=\"white\" data-source-background=\"brown\" style=\"color:#ffffff;background-color:#a43725\">否</span><strong class=\"source-bold\">の分かれ目</strong> <span data-source-border=\"brown\" data-source-border-style=\"dotted\" style=\"border:1px dotted #a43725\"><strong class=\"source-bold\">3つのマクドナルド内閣の違い</strong></span></h3>\n<blockquote><p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第1次マクドナルド労働党内閣</strong></span> ［1924］ ……<strong class=\"source-bold\">自由党との連立政権</strong></p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第4回選挙法改正</strong></span>［1918］ののち、労働党が<strong class=\"source-bold\">議会内第2党</strong>となり成立</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソ連の承認</strong></span>などをおこなったが、短期間で崩壊</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第2次マクドナルド労働党内閣</strong></span> ［1929〜31］ ……<strong class=\"source-bold\">労働党の単独政権</strong></p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第5回選挙法改正</strong></span>［1928］ののち、労働党が<strong class=\"source-bold\">議会内第1党</strong>となり成立</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">失業保険の削減</strong></span>で労働党の批判を受け、<strong class=\"source-bold\">総辞職</strong></p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マクドナルド挙国一致内閣</strong></span> ［1931〜35］ ……<strong class=\"source-bold\">実質的には保守党政権</strong></p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><strong class=\"source-bold\">労働党を除名</strong>されたマクドナルドが、<strong class=\"source-bold\">保守党・自由党と組んで</strong>成立</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">イギリスが伝統的な自由貿易を捨てて、ブロック経済を採択！</strong></span></h4>\n<p><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マクドナルド挙国一致内閣</strong></span>ができると、イギリスでも本格的な恐慌対策が始まった。まず、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">金本位制を停止</strong></span>してポンドを切り下げたから（<strong class=\"source-bold\">ポンド<ruby>安<rt>やす</rt></ruby></strong>）、イギリスの<strong class=\"source-bold\">輸出産業</strong>はなんとか持ちこたえられた。しかし、もっと大きな変化は、<strong class=\"source-bold\">伝統的な自由貿易政策を捨てた</strong>ことだよ。アメリカがスムート＝ホーリー関税法で関税を引き上げたことをきっかけに、イギリスも1932年に<strong class=\"source-bold\">輸入関税法（保護関税法）</strong>を制定してアメリカに対抗したんだ。そして<strong class=\"source-bold\">広大な植民地と連携</strong>して、<strong class=\"source-bold\">保護貿易</strong>によって恐慌から脱出しよう！って考えたんだ。</p>\n<p>とはいっても、植民地が協力してくれないとどうにもならない……。イギリスは、1931年の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ウェストミンスター憲章</strong></span>で「<strong class=\"source-bold\">本国と自治領が平等</strong>」な<strong class=\"source-bold\">イギリス連邦</strong>を発足させ、「みんなでこの経済危機を乗り切ろう！」って呼びかけた。イギリス本国だけじゃ、もはやムリってことだ……。</p>\n<blockquote><p>イギリスは植民地がいっぱいあるから、ブロック経済でなんとかなる！　じゃあ、植民地がない国はどうしたらいいんだろう？</p></blockquote>\n<p>こうして1932年、<strong class=\"source-bold\">カナダ</strong>の首都<strong class=\"source-bold\">オタワ</strong>で<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イギリス連邦経済会議</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">オタワ連邦会議</strong></span>】</strong>が開かれ、恐慌克服のために<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブロック経済</strong></span>方式が採択されたよ。これは、イギリス連邦に関税ブロック（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スターリング＝ブロック</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ポンド＝ブロック</strong></span>】</strong>）をつくり、連邦内の貿易にかかる関税は安く、その他の国からの輸入にかかる関税を高くして（これが「<strong class=\"source-bold\">特恵関税制度</strong>」だ）、連邦内の貿易を活発にして恐慌を克服しましょう！ってことだよ。イギリスは<strong class=\"source-bold\">完全に保護貿易に転換</strong>しちゃったね。こんなことしたら、世界の貿易はますます縮小しちゃうよ。</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "336": "<h2>336</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第18回</strong></span> 世界恐慌とその影響</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">イギリスのあとを追うように、フランスもブロック経済を形成！</strong></span></h4>\n<p>もともと<strong class=\"source-bold\">農業国だったフランス</strong>は、<ruby>恐慌<rt>きょうこう</rt></ruby>の影響を受けるのがほかの国よりも遅かったし、しかもアメリカに次いで<strong class=\"source-bold\">世界2位の金準備</strong>があったから、<strong class=\"source-bold\"><ruby>金本位制<rt>きんほんいせい</rt></ruby>を維持</strong>できた。そこでフランスは、イギリスのつくったブロック経済をパクって、金本位制を維持する<strong class=\"source-bold\">ベルギーやオランダ</strong>とともに<strong class=\"source-bold\">フラン＝ブロック</strong>（別名を“金＝ブロック”ともいうよ）をつくったよ。ただ、<strong class=\"source-bold\">各国が金本位制を停止</strong>して通貨を切り下げると（イギリスのポンド切り下げや、アメリカのドル切り下げ）、フランスからの<strong class=\"source-bold\">輸出が激減</strong>して、深刻な<ruby>不況<rt>ふきょう</rt></ruby>になってしまったんだ。</p>\n<p>経済が落ち込んだことで、国内では<strong class=\"source-bold\"><ruby>右翼<rt>うよく</rt></ruby>勢力の活動</strong>が活発になり、さらにドイツで<strong class=\"source-bold\">ナチ党政権が誕生</strong>すると、フランスでも「軍備を拡大してドイツを<ruby>潰<rt>つぶ</rt></ruby>せ！」というような過激な主張が現れ、ナチ党と同じようなファシズム団体ができたんだよ。</p>\n<p>危機感を持った左派の<strong class=\"source-bold\">社会党と共産党</strong>は協力して右翼と戦うことを決めたよ。最初は「社会党なんていう中途半端な連中と組むのは許さん！」と言っていたソ連のスターリンも、ファシズム勢力が力を強めるなかで方針を転換し、1935年の<strong class=\"source-bold\">コミンテルン第7回大会</strong>では<strong class=\"source-bold\">反ファシズムを結集</strong>する<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">人民戦線</strong></span>（反ファシズム統一戦線）戦術が<ruby>採択<rt>さいたく</rt></ruby>されたんだ。こうして、<strong class=\"source-bold\">社会党、共産党、急進社会党</strong>（社会主義じゃなかったよね）が協力して選挙で勝利し、1936年には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブルム</strong></span>を首相とする<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">人民戦線内閣</strong></span>が成立したよ。人民戦線内閣では、労働時間の短縮や有給休暇制など、<strong class=\"source-bold\">労働条件の改善</strong>などがおこなわれたんだけど、<strong class=\"source-bold\">スペイン内戦への対応</strong>から政権内部での対立が深まり、崩壊してしまったんだ。</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">4</span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">世界恐慌後のドイツ　〜ナチス＝ドイツ体制の成立〜</strong></span></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">世界恐慌以前のナチ党は、単なる弱小政党だったのに……</strong></span></h4>\n<p>じゃあ、ドイツに進むよ。ドイツでは<strong class=\"source-bold\">世界恐慌の後にナチス＝ドイツ体制ができる</strong>んだけど、まずはナチ党の成立から順に見ていこう。</p>\n<p>最初、ミュンヘンの小さな右翼団体だった<strong class=\"source-bold\">ドイツ労働者党</strong>は、1920年に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国民社会主義ドイツ労働者党</strong></span>（通称というか<ruby>蔑称<rt>べっしょう</rt></ruby>が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ナチ党</strong></span>、党員や関連するメンバーが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ナチス</strong></span>だよ）と改称し、1921年には演説のうまさでのし上がった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヒトラー</strong></span>が党首になった。ナチ党は議会を基盤とする政党というより、どっちかといえば、ヒトラー個人の周りに集まった人たちがつくった政治団体だから、「<strong class=\"source-bold\">ナチ党の主張＝ヒトラーの主張</strong>」だ。じゃあ、何を主張していたんだろう？　ヒトラーって、ナチ党ができてから独裁者になるまで、言ってることはたいして変わらないんだ。</p>",
  "337": "<h2>337</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">4</strong></span> 世界恐慌後のドイツ　〜ナチス＝ドイツ体制の成立〜</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">クローズアップ</strong></span> <span data-source-color=\"black\" data-source-background=\"pink\" style=\"color:#222222;background-color:#f0a0a0\"><strong class=\"source-bold\">世界恐慌からヒトラーの独裁確立まで</strong></span></h3>\n<blockquote><p><span data-source-color=\"red\" style=\"color:#e52715\">●</span>世界恐慌とナチ党の<ruby>台頭<rt>たいとう</rt></ruby></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">世界恐慌</strong></span>の発生 ［1929］ <span data-source-color=\"green\" style=\"color:#315837\">➡</span><strong class=\"source-bold\">失業者の激増</strong>、工業生産の激減</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span>政局の混乱……<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヒンデンブルク</strong></span><strong class=\"source-bold\">大統領</strong>による<strong class=\"source-bold\">少数派内閣</strong>の任命</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><strong class=\"source-bold\">1930年選挙</strong>……<strong class=\"source-bold\">ナチ党が第2党</strong>となる（107議席）。共産党は77議席</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span>恐慌の悪化</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><strong class=\"source-bold\">ローザンヌ会議</strong> ［1932］ に向けた徹底的な<strong class=\"source-bold\">デフレ政策</strong></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➡</span>デフレ政策で恐慌がさらに悪化し、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ナチ党</strong></span>と<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">共産党</strong></span>が台頭</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➡</span>共産党の台頭を嫌う<strong class=\"source-bold\">保守派</strong>や<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中間層</strong></span>が、<strong class=\"source-bold\">反共を唱えるナチ党を支持</strong></p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span>ナチス＝ドイツ体制の成立</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1932年選挙</strong></span>……<strong class=\"source-bold\">ナチ党と共産党が<ruby>躍進<rt>やくしん</rt></ruby></strong></p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><strong class=\"source-bold\">ナチ党が第1党</strong>となるが、共産党の躍進で<strong class=\"source-bold\">大資本家がナチ党支持に転換</strong></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヒトラー内閣</strong></span>成立 ［1933.1］ ＝ ドイツ第三帝国の成立</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヒンデンブルク</strong></span>大統領が任命。ただし、当初は軍部や大資本家との連合政権</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➡</span>ヒトラーは直ちに<strong class=\"source-bold\">議会を解散</strong>。<strong class=\"source-bold\">共産党を弾圧</strong>して、独裁確立を目指した</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国会議事堂放火事件</strong></span> ［1933］ を口実に、<strong class=\"source-bold\">共産党を非合法化</strong></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➡</span>総選挙で、<strong class=\"source-bold\">ナチ党が圧勝</strong></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">全権委任法</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">授権法</strong></span>】</strong> ［1933］ <span data-source-color=\"green\" style=\"color:#315837\">➡</span>他の政党を活動禁止とし、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">一党独裁</strong></span>を完成</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span>ヒトラーが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>総統<rt>そうとう</rt></ruby></strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フューラー</strong></span>】</strong> に就任 ［1934.8］</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><strong class=\"source-bold\">ヒンデンブルク大統領の死後</strong>、ヒトラーは<strong class=\"source-bold\">大統領権限も兼任</strong>し、<strong class=\"source-bold\">独裁権を確立</strong></p></blockquote>\n<p>ヒトラーはまず「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴェルサイユ体制の打破</strong></span>」を掲げて、<strong class=\"source-bold\">ヴェルサイユ条約の<ruby>破棄<rt>はき</rt></ruby></strong>と<strong class=\"source-bold\">再軍備</strong>、<strong class=\"source-bold\">オーストリアとの<ruby>合併<rt>がっぺい</rt></ruby></strong>による<strong class=\"source-bold\">大ドイツ国家</strong>の建設を主張した。さらに<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">反ユダヤ主義</strong></span>（ユダヤ人の<ruby>根絶<rt>こんぜつ</rt></ruby>）と<strong class=\"source-bold\">ドイツ民族の優越</strong>、そして<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">反共産主義</strong></span>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">反共</strong></span>）を掲げていた。反ユダヤ主義と反共産主義っていうのは、セットで考えることもできる。だって、<strong class=\"source-bold\">マルクスはユダヤ人</strong>だから、ヒトラーに言わせりゃ「共産主義はユダヤ人の<ruby>陰謀<rt>いんぼう</rt></ruby>」だよ。そして、共和国政権を<ruby>潰<rt>つぶ</rt></ruby>すための武装集団として<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>突撃隊<rt>とつげきたい</rt></ruby></strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">SA</strong></span>】</strong>や<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>親衛隊<rt>しんえいたい</rt></ruby></strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">SS</strong></span>】</strong>をつくった。右翼団体が軍隊持ってるのって危ないよね。</p>\n<p>そして1923年、<strong class=\"source-bold\">ルール<ruby>占領<rt>せんりょう</rt></ruby>とインフレーション</strong>による混乱を見たヒトラーは、保守派による軍部クーデタのきっかけをつくろうと、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ミュンヘン<ruby>一揆<rt>いっき</rt></ruby></strong></span>を起こした。しかし、期待していた軍部のクーデタは起こらず、<strong class=\"source-bold\">ヒトラーは逮捕・投獄</strong>されたんだ。ただ、保守的なドイツの司法に特別扱いを受けたヒトラーは、獄中では『<strong class=\"source-bold\">わが闘争</strong>』を口述筆記したよ。内容はこれまでの主張をまとめただけだから、目新しいことは何もないけど、この時ヒトラーは<strong class=\"source-bold\">今後の作戦を考え直した</strong>。これまでは武装クーデタで政権を潰そうとしてきたけど、武装<ruby>蜂起<rt>ほうき</rt></ruby>だと国軍の大半が味方にならな</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "338": "<h2>338</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第18回</strong></span> 世界恐慌とその影響</p>\n<p>いと成功しない。だったら<strong class=\"source-bold\">選挙で「合法的」に政権を奪おう</strong>！って決めたんだよ。</p>\n<p>こうしてヒトラーは、選挙での勢力拡大を目指して全国に組織を広げ、現状に不満を持つ勢力を吸収しようとした。かといって、いきなり大勢力になったわけじゃない。だって、うさん<ruby>臭<rt>くさ</rt></ruby>い<ruby>右翼<rt>うよく</rt></ruby>団体じゃん。しかも、<strong class=\"source-bold\">ドーズ案</strong>によるアメリカ資本の流入で<strong class=\"source-bold\">ドイツ経済が<ruby>復興<rt>ふっこう</rt></ruby></strong>してくると、現状に不満を持ってる人が減るから、<strong class=\"source-bold\">ナチ党の勢力も後退し始めた</strong>はずだったんだけど……。世界<ruby>恐慌<rt>きょうこう</rt></ruby>のあと、状況が大きく変わってしまうんだよ！。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">世界恐慌の影響で失業者が激増！　社会不安の増大から政局が混乱</strong></span></h4>\n<p>アメリカ資本によって復興を進めていた<strong class=\"source-bold\">ドイツ</strong>は、恐慌の影響が一番ひどかった。1930年には<strong class=\"source-bold\">工業生産が約7割も減り</strong>、<strong class=\"source-bold\">失業者も300万人を超えて</strong>、失業保険の支払いが追いつかなくなった。人びとは全く<strong class=\"source-bold\">先の見えない不安感</strong>に襲われていたんだ。こうして<strong class=\"source-bold\">社会民主党政権が崩壊</strong>したんだけど、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヒンデンブルク</strong></span>大統領は社会民主党を嫌って、少数派（中央党）のブリューニングを首相にした。そして、議会で多数派になることを狙って議会を解散し、<strong class=\"source-bold\">1930年に総選挙</strong>がおこなわれたんだけど、この政局の混乱がナチ党を押し上げる結果になってしまったんだ。</p>\n<p>ヒトラーは、「現在の政権は無責任である！　私の個人<ruby>独裁<rt>どくさい</rt></ruby>によって、責任を持ってドイツを復活させる」と主張して支持を集め、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ナチ党</strong></span>は107議席を獲得して<strong class=\"source-bold\">議会内第2党</strong>まで躍進したよ。一方で「恐慌の克服は、ソ連の方法（五カ年計画、つまり社会主義だ）しかない！」と主張する<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">共産党</strong></span>も77議席を獲得して躍進した。どちらにせよ、議会内では<strong class=\"source-bold\">共和国を否定する勢力が強く</strong>なったから、ブリューニング政権は<strong class=\"source-bold\">大統領緊急令</strong>に頼って政治をするしかなかったんだ（<strong class=\"source-bold\">大統領内閣</strong>）。</p>\n<p>ブリューニングは協調外交をやめてヴェルサイユ体制の修正を目指し、ドイツの財政が<ruby>破綻<rt>はたん</rt></ruby>寸前であることを示して、<ruby>賠償金<rt>ばいしょうきん</rt></ruby>の廃止を各国に認めさせようとした。このため<strong class=\"source-bold\">失業保険の削減や公務員給与の引き下げ</strong>など、徹底的に支出を減らすデフレ政策をとったから、各国はドイツの状況を認めて、<strong class=\"source-bold\">ローザンヌ会議</strong>ではドイツの<strong class=\"source-bold\">賠償金が大幅に減額</strong>されたんだ（30億金マルクになった）。でも、この<strong class=\"source-bold\">デフレ政策</strong>でドイツ国内ではますます<strong class=\"source-bold\">恐慌が悪化</strong>！　1932年にはついに<strong class=\"source-bold\">失業者が600万人</strong>になってしまったから、ドイツ国民の不満は高まる一方だよ。「もはや、今の政府にはなんの希望もない！」と思った人びとは、徹底的に現状を批判する<strong class=\"source-bold\">ナチ党や共産党を支持</strong>したんだね。</p>\n<blockquote><p>共産党の台頭が、ナチ党が躍進した要因だよ！　「革命が起きたら大変だ！」って焦ったんだね</p></blockquote>",
  "339": "<h2>339</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">4</strong></span> 世界恐慌後のドイツ　〜ナチス＝ドイツ体制の成立〜</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">共産党の<ruby>躍進<rt>やくしん</rt></ruby>を恐れる保守派がナチ党を支持。ついにヒトラー政権成立！</strong></span></h4>\n<p>こうなると、<strong class=\"source-bold\">保守派や軍部</strong>、さらに<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中間層</strong></span>（比較的豊かな労働者など）は「これ以上<strong class=\"source-bold\">共産党の力が強まったら、革命が起きるのでは</strong>！」と焦ったんだ。「共産党を<ruby>潰<rt>つぶ</rt></ruby>してくれそうなのは誰だ？」と考えた時に、徹底的な<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">反共産主義</strong></span>を主張していたのが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ナチ党</strong></span>、というかヒトラーだったから、<strong class=\"source-bold\">ヒトラーへの支持</strong>が集まってしまった。1932年の大統領選挙で敗れたけど、ヒトラーはヒンデンブルク大統領の一番有力な<ruby>対抗馬<rt>たいこうば</rt></ruby>になって存在感を見せつけた。そして、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1932年の国会選挙</strong></span>では、ついに<strong class=\"source-bold\">ナチ党が議会内第1党</strong>になったんだ。11月の選挙でナチ党は少し議席を減らす（7月230議席→11月196議席）一方で、保守派、特に<strong class=\"source-bold\">ユンカー</strong>（彼らの政党が<strong class=\"source-bold\">国家人民党</strong>だ）や大資本家を驚かせたのは<strong class=\"source-bold\">共産党の躍進</strong>だ（7月89議席→11月100議席）。「共産党を抑え込むには、大衆の支持を得ているヒトラーと組むしかない」と考えた<strong class=\"source-bold\">ユンカーや大資本家はヒトラーを支持</strong>し、ヒンデンブルク大統領に圧力をかけた。ヒトラーを首相にしたくなかった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヒンデンブルク</strong></span>は、相変わらず<strong class=\"source-bold\">少数派内閣</strong>を任命したんだけど（パーペン内閣→シュライヒャー内閣）、大衆の支持が全く得られないまま圧力に屈し、議会内第1党の党首である<strong class=\"source-bold\">ヒトラーを首相に任命</strong>するしかなくなった。</p>\n<p>こうして1933年、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヒトラー内閣</strong></span>が成立したんだけど、実際は<strong class=\"source-bold\">軍部や大資本家の支援</strong>でできた連合政権だったから、ナチ党から内閣に入ったのはわずか3人だった。保守派の連中はヒトラーを「<ruby>飼<rt>か</rt></ruby>いならして」、自分たちの思い通りに動かせると思っていたんだけど、それが甘かったんだよ。それから、ヒトラーが政権に就いてからを「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ナチス＝ドイツ</strong></span>」と呼ぶこともあるからね。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">次々と反対派を倒し、あっという間にヒトラーが独裁権を確立！</strong></span></h4>\n<p>首相に就任した直後、ヒトラーはラジオを通じて2時間を超える演説をおこない、ヴェルサイユ体制やこれまでの政権への批判を繰り広げた。さらに「ドイツ国民の未来は、ドイツ国民のうちにある」とドイツ人のプライドに訴えて支持を呼びかけると、政権獲得の2日後には保守派の反対を押し切って<strong class=\"source-bold\">議会を解散</strong>したんだ。これは左翼勢力、特に共産党を潰して<strong class=\"source-bold\">ナチ党単独で過半数を取ろう</strong>！っていう<ruby>企<rt>たくら</rt></ruby>みだ。そして、選挙戦の終盤に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国会議事堂放火事件</strong></span>が起きて、オランダの元共産党員だったルッベが逮捕されると、ヒトラーはこれを「<strong class=\"source-bold\">共産党の<ruby>仕業<rt>しわざ</rt></ruby>である</strong>」と断定したよ。この事件は<strong class=\"source-bold\">ナチスの自作自演との説もある</strong>けど、真相はよくわかんない……。ただ、どっちにしてもこの事件をきっかけに、ヒトラーは<strong class=\"source-bold\">憲法の基本的人権停止</strong>を決めて、<strong class=\"source-bold\">共産党員を次々と拘束</strong>し<ruby>弾圧<rt>だんあつ</rt></ruby>したんだよ！。</p>\n<p>こうして実施された総選挙で、<strong class=\"source-bold\">ナチ党は288議席を獲得して勝利</strong>したものの、<strong class=\"source-bold\">単独で過半数を取れなかった</strong>（約45％）。この時、保守派の国家人民党と合わせてなんとか過半数になった程度なんだよ。実は<strong class=\"source-bold\">左派勢力は全然弱くなっていない</strong>。これほどの弾圧にもかかわらず、共産党は81議席を獲得していたし、社会民主党も1932年の選挙とほぼ同じ120議席だったからね。選挙で左派を潰せなかったヒトラー</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "340": "<h2>340</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第18回</strong></span> 世界恐慌とその影響</p>\n<p>は、議会を無力にするために、非合法にした<strong class=\"source-bold\">共産党の議席を<ruby>剥奪<rt>はくだつ</rt></ruby></strong>し、さらに右派の国家人民党と<ruby>中道<rt>ちゅうどう</rt></ruby>路線をとる中央党を引き込んで<strong class=\"source-bold\">全議席の3分の2を確保</strong>すると、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">全権委任法</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">授権法</strong></span>】</strong>を成立させた。この法律は、以後4年間、<strong class=\"source-bold\">ヒトラー政権に立法権を<ruby>委<rt>ゆだ</rt></ruby>ねる</strong>というもので、憲法違反の内容が含まれてもいい、というとんでもない内容だよ。これで、ヒトラーは好き勝手な法律を、いつでもつくれるようになったんだ。</p>\n<blockquote><p>全権委任法の成立で、もはや議会は何もできなくなったから、「国会の自殺」っていわれたんだ</p></blockquote>\n<p>こうなると、ヒトラーを止められるものはない。ナチ党以外の<strong class=\"source-bold\">他の政党を活動禁止</strong>として<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">一党<ruby>独裁<rt>どくさい</rt></ruby></strong></span>を完成させると、すべての<strong class=\"source-bold\">労働組合を解散</strong>してナチス主導のドイツ労働戦線に強制的に統合した。さらに、州の自治権を廃止して連邦制から<strong class=\"source-bold\">中央集権国家に移行</strong>すると、<strong class=\"source-bold\">ナチ党内部での<ruby>粛清<rt>しゅくせい</rt></ruby></strong>も始まった。<ruby>突撃隊<rt>とつげきたい</rt></ruby>の権限強化を主張していたレームや、帝政復活を狙っていた反ナチスの保守派を暗殺して（レーム事件）、軍と<ruby>親衛隊<rt>しんえいたい</rt></ruby>を強化して権力をヒトラーに集中させた。そして、<strong class=\"source-bold\">ヒンデンブルク大統領の死後</strong>、ヒトラーは大統領権限も自分のものにして「<strong class=\"source-bold\">第三帝国</strong>」の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>総統<rt>そうとう</rt></ruby></strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フューラー</strong></span>】</strong>に就任し、<strong class=\"source-bold\">国家元首（大統領）、首相、最高軍司令官、党首</strong>の全権を握ったんだ。</p>\n<h4><span data-source-color=\"gray\" style=\"color:#777777\"><strong class=\"source-bold\">ヒトラー政権は失業問題を解決！　とはいっても、大半は軍需産業だよ……</strong></span></h4>\n<p>じゃあ、ヒトラー独裁下のドイツ国内の状況について見ていこう。ヒトラー政権の政策をつくっていたのは、ナチ党のNo.2だった<strong class=\"source-bold\">ゲーリング</strong>だ。ゲーリングはまず、<strong class=\"source-bold\">ゲシュタポ【国家秘密警察】</strong>をつくって国内で<strong class=\"source-bold\">ナチスに反対する連中を次々と<ruby>抹殺<rt>まっさつ</rt></ruby></strong>した。この恐怖政治はゲシュタポと親衛隊を中心におこなわれたから、指揮をしたのは親衛隊の中心<strong class=\"source-bold\">ヒムラー</strong>だ。あっ、ヒムラーはヒトラーの<ruby>誤植<rt>ごしょく</rt></ruby>じゃないよ。</p>\n<p>そしてヒトラーは、<strong class=\"source-bold\">恐慌を克服</strong>するための経済政策として、失業者を減らすために、大々的な<strong class=\"source-bold\">公共事業と軍備拡大</strong>をおこなったんだ。でも、この時にやったことは、すでに<strong class=\"source-bold\">ヒトラーが政権に就く前から計画されていたものもある</strong>。例えば、<strong class=\"source-bold\">アウトバーン</strong>（高速道路）建設は、すでに工事が始まっていたものを、ヒトラーが自分の手柄のように大々的に宣伝したものだ。そして1936年から「<strong class=\"source-bold\">四カ年計画</strong>」が始まったよ。なんかソ連の五カ年計画のパクリっぽいけど、「ロシア人だと5年かかるのを、ドイツ人は優秀だから4年で終わる」ってこと。ここで<strong class=\"source-bold\">最優先されたのが軍備拡大</strong>！　例えば、輸入に頼っているゴム、石油、繊維などを国内でとれる石炭から合成して自給する計画（<strong class=\"source-bold\">アウタルキー</strong>）なんてのもあったんだけど、これも軍備拡大に必要な資源の確保に困ったヒトラーが、なんとか自給を目指したものだ。</p>\n<p>このように<strong class=\"source-bold\">軍需産業と公共事業に失業者を吸収</strong>した結果、ドイツの失業者は600万人から、なんと50万人にまで減少したんだよ。これで、ほぼ<strong class=\"source-bold\">失業問題は解決した</strong>、っていってもいい。だから、ナチスを批判しようとすると「あなたは<ruby>恐慌<rt>きょうこう</rt></ruby>の時</p>",
  "341": "<h2>341</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">4</strong></span> 世界恐慌後のドイツ　〜ナチス＝ドイツ体制の成立〜</p>\n<p>にどんな生活をしていましたか？　今、こうして普通の生活ができるのはヒトラーのおかげですよ」と言われるの……。この時点で、<strong class=\"source-bold\">完全に恐慌を克服したのはドイツだけ</strong>だったからね。そして、このドイツの経済的繁栄を世界に示したのが、1936年の<strong class=\"source-bold\">ベルリン＝オリンピック</strong>だよ。おそらく、史上初めて全面的に政治利用されたオリンピックだ。さらに、歓喜力行団という組織が<strong class=\"source-bold\">団体旅行などのレクリエーション</strong>を企画して、国民の一体感を演出した。そして1937年には、ついに完全雇用状態を達成して、一部では<strong class=\"source-bold\">労働力が不足</strong>するようになっていた。この労働力不足が、<strong class=\"source-bold\">ナチス＝ドイツが対外侵略する動機</strong>の1つになったんだよ。</p>\n<h3>＋<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">α</strong></span><u data-source-underline-color=\"black\" style=\"text-decoration-color:#222222\"><strong class=\"source-bold\">ちょっと寄り耳</strong></u> <span data-source-marker=\"curved-arrow\" data-source-color=\"black\" style=\"color:#222222\">⤴</span></h3>\n<blockquote><p>入試のためとはいえ、毎年授業をしていくなかで必ず話をしているのが、ヒトラーのユダヤ人<ruby>根絶<rt>こんぜつ</rt></ruby>、いわゆる「ホロコースト」なんだ。歴史上、これほどまでに組織的に、かつ冷静な計算に基づいて、特定の民族の根絶を目指したものはない。というのも、ナチスのユダヤ人虐殺では、アウシュヴィッツなどの強制収容所で「処理できる人数」だけユダヤ人を計画的にゲットーから移動した。強制収容所に運び込まれた人は、「働けないもの＝即刻虐殺」「働ける者＝生かしておく」とふるいにかけられ、働けないとされた老人・女性・子どもなどは、シャワー室の形につくられたガス室で<ruby>青酸<rt>せいさん</rt></ruby>ガス（チクロンB）で殺され、生き残った者も強制労働や人体実験などさまざまな<ruby>拷問<rt>ごうもん</rt></ruby>を受けたんだ。ガス室で大量殺害している時には、収容所中に断末魔の叫び声が響き、そこで何がおこなわれているか、すぐにわかったそうだよ。しかし、収容所内のユダヤ人にはどうすることもできず、虐殺後の遺体はユダヤ人が運びだして焼いたんだ。さらに、生きている人から臓器を取るなどの人体実験もおこなわれ、特に、<ruby>双子<rt>ふたご</rt></ruby>の人の多くがその犠牲になったという。結局、第二次世界大戦期を通じて、少なく見ても600万人ものユダヤ人、ユダヤ人以外を合わせると800万人以上が、強制収容所で虐殺された。</p>\n<p>とても、これだけのスペースでみんなに伝えるのは難しいので、もし覚えていたら大学に入ったあとでいいので、自らユダヤ人として収容所に<ruby>囚<rt>とら</rt></ruby>われ、奇跡的に生還した心理学者フランクル教授の『夜と霧』という本を読んでみてほしい。僕自身、大学1年で読んだ時の衝撃は、これまで読んだどの本よりも強いものだったよ。そして、これを実行したナチス政権が、最初は選挙で「第1党」になってできたという事実……。みんなも、もう参政権を手にする年齢だよね。平時であれば冷静な判断もできるかもしれない。でも、もし恐慌のような極限状況になった時には、こうした人間としてあるまじき政権をつくる危険もあるんだよ。成人して選挙権を得るということは、そういう責任も持つということなんだ。自分が得た権利の重さと大切さを考えて、自分の良心に照らして選挙で投票してもらえたら、僕がこうして歴史を語った意味もあったんだろうと思っています。</p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "342": "<h2>342</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第18回</strong></span> 世界恐慌とその影響</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ドイツ人の「民族共同体」をつくるため、組織的にユダヤ人を<ruby>迫害<rt>はくがい</rt></ruby>した</strong></span></h4>\n<p>ヒトラーは「<strong class=\"source-bold\">ドイツ民族の優越</strong>」を主張していたから、そのドイツ人の<strong class=\"source-bold\">民族共同体</strong>に合わない人間は排除するという政策をとった。このなかで、排除されるべき人間として標的になったのが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ユダヤ人</strong></span>だよ。1935年に制定された<strong class=\"source-bold\">ニュルンベルク法</strong>では、<strong class=\"source-bold\">ユダヤ人の公職追放、企業経営の禁止、財産没収</strong>、そして<strong class=\"source-bold\">ドイツ人との通婚禁止</strong>などが定められた。この場合の「ユダヤ人」とは祖父母4人のうち3人が「ユダヤ人」の人のことだ（「ドイツ人」と「ユダヤ人」の中間に「<ruby>混血<rt>こんけつ</rt></ruby>者」という規定もあった）。ただ、<strong class=\"source-bold\">ユダヤ人っていうのは本来「ユダヤ教徒」</strong>のことだから、はっきり言えば血の問題は関係ない。でもナチスにとって、そんなことはどうでもいい。ユダヤ人を劣等国民としてドイツ人の「民族共同体」から排除するのが目的だからね。だから、ユダヤ人以外にも<strong class=\"source-bold\">ロマ</strong>（シンティ・ロマ、<ruby>蔑称<rt>べっしょう</rt></ruby>が「ジプシー」）なども「<ruby>異分子<rt>いぶんし</rt></ruby>」として迫害の対象になったんだ。</p>\n<p>そして、パリのドイツ大使館員がユダヤ人青年に殺害された事件の報復として、ナチスが全国に<strong class=\"source-bold\">集団的迫害</strong>（「<strong class=\"source-bold\">ポグロム</strong>」）を指示すると、<ruby>突撃隊<rt>とつげきたい</rt></ruby>を中心に<strong class=\"source-bold\">ユダヤ人商店の破壊・放火、ユダヤ人の襲撃</strong>と大量<ruby>拘束<rt>こうそく</rt></ruby>（なんと2万人以上！）がおこなわれたんだ。この「<strong class=\"source-bold\"><ruby>水晶<rt>すいしょう</rt></ruby>の夜【クリスタルナハト】</strong>」事件をきっかけに、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ユダヤ人迫害</strong></span>はエスカレートしていった。ユダヤ人は<strong class=\"source-bold\">ゲットー</strong>（特定のユダヤ人居住地区）に<strong class=\"source-bold\">強制移住</strong>させられ、持っていた不動産は強制的に売却された。これが、大戦<ruby>勃発<rt>ぼっぱつ</rt></ruby>後にドイツがヨーロッパを制圧するとヨーロッパ全体でおこなわれ、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アウシュヴィッツ</strong></span>などの<strong class=\"source-bold\">強制収容所で大量虐殺</strong>がおこなわれる布石となった。そして、<strong class=\"source-bold\">ユダヤ系</strong>、あるいはユダヤ系ではなくても<strong class=\"source-bold\">反ナチス的</strong>とされた知識人たちは、<strong class=\"source-bold\">海外へと<ruby>亡命<rt>ぼうめい</rt></ruby></strong>するしかなかった。この時に亡命した人には、ユダヤ人物理学者<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アインシュタイン</strong></span>やドイツ人作家<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">トーマス＝マン</strong></span>などがいるね。こうした迫害は、第二次世界大戦中になると、<strong class=\"source-bold\">ユダヤ民族の根絶</strong>を目指す計画的虐殺（「<strong class=\"source-bold\">ホロコースト</strong>」）となったんだ。</p>\n<p>今回はこれでおしまい。最後に年号checkしよう！</p>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">!!</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">年号</strong></span><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">のツボ</strong></span></h3>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">世界<ruby>恐慌<rt>きょうこう</rt></ruby></strong> ［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1929</strong></span>］ （<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>引<rt>1</rt></ruby><ruby>く<rt>9</rt></ruby><ruby>に<rt>2</rt></ruby></strong></span>も<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>苦<rt>9</rt></ruby></strong></span>しい　世界恐慌）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">フーヴァー＝モラトリアム</strong> ［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1931</strong></span>］ （<ruby>賠償<rt>ばいしょう</rt></ruby>・<ruby>戦債<rt>せんさい</rt></ruby>　<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>1<rt>1</rt></ruby></strong></span>年<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>救<rt>9</rt></ruby><ruby>済<rt>31</rt></ruby></strong></span>）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">オタワ連邦会議</strong> ［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1932</strong></span>］ （<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>いち<rt>1</rt></ruby></strong></span>も<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>く<rt>9</rt></ruby><ruby>さん<rt>3</rt></ruby><ruby>に<rt>2</rt></ruby></strong></span>　ブロック経済）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">ニューディールの開始</strong> ［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1933</strong></span>］ （<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>戦<rt>19</rt></ruby><ruby>さ<rt>3</rt></ruby><ruby>見<rt>3</rt></ruby></strong></span>ないで　ダム造る）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">ヒトラー政権の成立</strong> ［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1933</strong></span>］ （これから<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>独<rt>19</rt></ruby><ruby>裁<rt>3</rt></ruby></strong></span>　第<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>三<rt>3</rt></ruby></strong></span>帝国）</p>\n<p>次回は<strong class=\"source-bold\">第二次世界大戦に突入</strong>！　ヒトラーの野望がどんどん大きくなるのに、周りの国は何をしてたんだろう……。近現代史も大詰めだよ。</p>"
};

